import json

def subsets(n):
    for bits in range(1 << n):
        yield frozenset(i for i in range(n) if (bits >> i) & 1)

def find_counterexample(prem, concl, maxn=3):
    # Exhaustive search over finite models: universe size 1..maxn,
    # every extension of predicate X and predicate Y.
    for n in range(1, maxn + 1):
        U = range(n)
        for X in subsets(n):
            for Y in subsets(n):
                if prem(U, X, Y) and not concl(U, X, Y):
                    return {"universe_size": n, "X": sorted(X), "Y": sorted(Y)}
    return None

# Original argument: "Some good things are not cheap; therefore some cheap things are not good."
# X = good, Y = cheap
orig_prem = lambda U, X, Y: any(x in X and x not in Y for x in U)
orig_concl = lambda U, X, Y: any(x in Y and x not in X for x in U)

options = {
    # A: some Hunan people don't like pepper -> some pepper-likers aren't from Hunan
    "A": (lambda U, X, Y: any(x in X and x not in Y for x in U),
          lambda U, X, Y: any(x in Y and x not in X for x in U)),
    # B: some people aren't selfish -> people aren't all selfish (X = selfish, Y unused)
    "B": (lambda U, X, Y: any(x not in X for x in U),
          lambda U, X, Y: not all(x in X for x in U)),
    # C: good motive not necessarily good effect -> good results not necessarily from good motive
    "C": (lambda U, X, Y: any(x in X and x not in Y for x in U),
          lambda U, X, Y: any(x in Y and x not in X for x in U)),
    # D: some southerners aren't Cantonese -> not all Cantonese are southerners
    "D": (lambda U, X, Y: any(x in X and x not in Y for x in U),
          lambda U, X, Y: any(x in Y and x not in X for x in U)),
}

orig_counter = find_counterexample(orig_prem, orig_concl)

results = {}
for key, (p, c) in options.items():
    ce = find_counterexample(p, c)
    results[key] = {"has_counterexample": ce is not None, "counterexample": ce}

# The original form has a counterexample (invalid: O-to-O conversion).
# Options with a counterexample share that invalid form; the option with none is the valid one.
valid_options = [k for k, v in results.items() if not v["has_counterexample"]]

if len(valid_options) == 1:
    final_answer = valid_options[0]
else:
    final_answer = "UNSUPPORTED"

output = {
    "final_answer": final_answer,
    "evidence": {
        "original_has_counterexample": orig_counter is not None,
        "original_counterexample": orig_counter,
        "options": results,
    },
}

print(json.dumps(output, sort_keys=True))
